    f = (I/p['Ki'])**p['h']
    return p['Vmax']*S/(p['Km']*(1+f)+S)

PARAMS = ['Vmax','Km','Ki','beta']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    f = I/p['Ki']
    # competitive inhibition plus partial loss of Vmax with inhibitor (floor = beta)
    return p['Vmax']*(p['beta']+(1-p['beta'])/(1+f))*S/(p['Km']*(1+f)+S)

